import { ListFilter, Plus, Search } from '@gntik-ai/icons';
import {
  Button,
  cn,
  Input,
  Menu,
  MenuCheckboxItem,
  MenuContent,
  MenuGroup,
  MenuGroupLabel,
  MenuSeparator,
  MenuTrigger,
  SimpleSelect,
  Token,
} from '@gntik-ai/ui';
import { Fragment, useState } from 'react';
import { useFilterBarLabels, type FilterBarLabels } from './labels';
export type { FilterBarLabels } from './labels';
import { DEPLOYMENT_DEFAULT_FILTERS, DEPLOYMENT_FILTER_FIELDS, DEPLOYMENT_SAVED_VIEWS } from './fixtures';

export interface FilterField {
  id: string;
  label: string;
  options: readonly string[];
}

export interface ActiveFilter {
  field: string;
  value: string;
}

export interface SavedView {
  value: string;
  label: string;
  query?: string;
  filters: readonly ActiveFilter[];
}

export interface FilterBarProps {
  fields?: readonly FilterField[];
  /** Search text (controlled). */
  query?: string;
  defaultQuery?: string;
  onQueryChange?: (query: string) => void;
  /** Active filters (controlled). */
  filters?: readonly ActiveFilter[];
  defaultFilters?: readonly ActiveFilter[];
  onFiltersChange?: (filters: ActiveFilter[]) => void;
  /** Saved views; picking one applies its query and filters. Empty hides the Select. */
  views?: readonly SavedView[];
  defaultView?: string | null;
  onViewChange?: (view: SavedView) => void;
  searchLabel?: string;
  placeholder?: string;
  /** Optional result count shown at the end ("12 results"). */
  resultCount?: number;
  labels?: FilterBarLabels;
  className?: string;
}

const same = (a: ActiveFilter, b: ActiveFilter) => a.field === b.field && a.value === b.value;

/**
 * Filter bar: search Input, saved views Select, an "Add filter" Menu (multi-select per field),
 * removable filter chips (Token) and Clear all.
 */
export function FilterBar({
  fields = DEPLOYMENT_FILTER_FIELDS,
  query: queryProp,
  defaultQuery = '',
  onQueryChange,
  filters: filtersProp,
  defaultFilters = DEPLOYMENT_DEFAULT_FILTERS,
  onFiltersChange,
  views = DEPLOYMENT_SAVED_VIEWS,
  defaultView = null,
  onViewChange,
  searchLabel: searchLabelProp,
  placeholder: placeholderProp,
  resultCount,
  labels,
  className,
}: FilterBarProps) {
  const l = useFilterBarLabels(labels);
  const searchLabel = labels?.search ?? searchLabelProp ?? l.search;
  const placeholder = labels?.placeholder ?? placeholderProp ?? l.placeholder;
  const [innerQuery, setInnerQuery] = useState(defaultQuery);
  const [innerFilters, setInnerFilters] = useState<readonly ActiveFilter[]>(defaultFilters);
  const [view, setView] = useState<string | null>(defaultView);
  const query = queryProp ?? innerQuery;
  const filters = filtersProp ?? innerFilters;

  const setQuery = (next: string) => {
    setInnerQuery(next);
    onQueryChange?.(next);
  };
  const setFilters = (next: ActiveFilter[], keepView = false) => {
    setInnerFilters(next);
    onFiltersChange?.(next);
    if (!keepView) setView(null);
  };
  const toggle = (filter: ActiveFilter, on: boolean) =>
    setFilters(on ? [...filters.filter((f) => !same(f, filter)), filter] : filters.filter((f) => !same(f, filter)));
  const applyView = (value: string | null) => {
    const picked = views.find((v) => v.value === value);
    if (!picked) return;
    setView(picked.value);
    setFilters([...picked.filters], true);
    if (picked.query !== undefined) setQuery(picked.query);
    onViewChange?.(picked);
  };
  const clearAll = () => {
    setFilters([]);
    setQuery('');
  };
  const labelOf = (id: string) => fields.find((f) => f.id === id)?.label ?? id;
  const hasAny = filters.length > 0 || query !== '';

  return (
    <div role="search" aria-label={l.region} className={cn('flex flex-col gap-3', className)}>
      <div className="flex flex-col gap-2 sm:flex-row sm:items-center">
        <Input
          aria-label={searchLabel}
          type="search"
          size="sm"
          leadingIcon={Search}
          placeholder={placeholder}
          value={query}
          onValueChange={(v) => setQuery(String(v))}
          className="w-full sm:max-w-xs"
        />
        <div className="flex flex-wrap items-center gap-2">
          {views.length > 0 && (
            <SimpleSelect
              aria-label={l.savedView}
              size="sm"
              placeholder={l.savedViews}
              value={view}
              onValueChange={applyView}
              items={views.map((v) => ({ value: v.value, label: v.label }))}
              className="min-w-[160px]"
            />
          )}
          <Menu>
            <MenuTrigger render={<Button variant="secondary" size="sm" icon={Plus} />}>{l.addFilter}</MenuTrigger>
            <MenuContent className="max-h-80 min-w-[220px] overflow-y-auto">
              {fields.map((field, i) => (
                <Fragment key={field.id}>
                  {i > 0 && <MenuSeparator />}
                  <MenuGroup>
                    <MenuGroupLabel>{field.label}</MenuGroupLabel>
                    {field.options.map((option) => {
                      const filter = { field: field.id, value: option };
                      return (
                        <MenuCheckboxItem
                          key={option}
                          checked={filters.some((f) => same(f, filter))}
                          onCheckedChange={(on) => toggle(filter, on)}
                        >
                          {option}
                        </MenuCheckboxItem>
                      );
                    })}
                  </MenuGroup>
                </Fragment>
              ))}
            </MenuContent>
          </Menu>
        </div>
        {resultCount !== undefined && (
          <p className="text-[12.5px] text-muted-foreground sm:ms-auto" aria-live="polite">
            {labels?.resultCount ? (
              labels.resultCount(resultCount)
            ) : (
              <>
                <span className="font-mono text-foreground tabular-nums">{resultCount.toLocaleString('en-US')}</span>{' '}
                {resultCount === 1 ? 'result' : 'results'}
              </>
            )}
          </p>
        )}
      </div>
      {hasAny && (
        <div className="flex flex-wrap items-center gap-2">
          <span className="inline-flex items-center gap-1.5 font-mono text-[10px] tracking-[0.14em] text-muted-foreground uppercase">
            <ListFilter size={12} aria-hidden />
            {l.filters}
          </span>
          <ul aria-label={l.activeFilters} className="flex flex-wrap items-center gap-2">
            {filters.map((f) => (
              <li key={`${f.field}:${f.value}`} className="flex">
                <Token
                  size="sm"
                  prefix={`${labelOf(f.field)}:`}
                  label={f.value}
                  removeLabel={l.removeFilter(labelOf(f.field), f.value)}
                  onRemove={() => toggle(f, false)}
                />
              </li>
            ))}
          </ul>
          <Button variant="ghost" size="sm" className="h-7 px-2 hover:text-destructive-text" onClick={clearAll}>
            {l.clearAll}
          </Button>
        </div>
      )}
    </div>
  );
}

import type { ActiveFilter, FilterField, SavedView } from './FilterBar';

export const DEPLOYMENT_FILTER_FIELDS: FilterField[] = [
  { id: 'status', label: 'Status', options: ['Running', 'Queued', 'Paused', 'Degraded', 'Failed'] },
  { id: 'region', label: 'Region', options: ['eu-west-1', 'us-east-1', 'ap-south-1', 'eu-central-1'] },
  { id: 'owner', label: 'Owner', options: ['Platform team', 'Payments team', 'Data team'] },
];

export const DEPLOYMENT_DEFAULT_FILTERS: ActiveFilter[] = [
  { field: 'status', value: 'Running' },
  { field: 'region', value: 'eu-west-1' },
];

export const DEPLOYMENT_SAVED_VIEWS: SavedView[] = [
  { value: 'all', label: 'All deployments', filters: [] },
  {
    value: 'attention',
    label: 'Needs attention',
    filters: [
      { field: 'status', value: 'Degraded' },
      { field: 'status', value: 'Failed' },
    ],
  },
  {
    value: 'eu',
    label: 'EU regions',
    filters: [
      { field: 'region', value: 'eu-west-1' },
      { field: 'region', value: 'eu-central-1' },
    ],
  },
];

import { useI18n } from '@gntik-ai/ui';

export interface FilterBarLabels {
  region?: string;
  search?: string;
  placeholder?: string;
  savedView?: string;
  savedViews?: string;
  addFilter?: string;
  activeFilters?: string;
  filters?: string;
  clearAll?: string;
  removeFilter?: (field: string, value: string) => string;
  /** Whole polite live-region text, with a raw count. */
  resultCount?: (count: number) => string;
}

export function useFilterBarLabels(labels?: FilterBarLabels) {
  const { t } = useI18n();
  return {
    region: labels?.region ?? t('filters.label'),
    search: labels?.search ?? t('common.search'),
    placeholder: labels?.placeholder ?? 'Search by name…',
    savedView: labels?.savedView ?? t('filters.savedView'),
    savedViews: labels?.savedViews ?? t('filters.savedViews'),
    addFilter: labels?.addFilter ?? t('filters.add'),
    activeFilters: labels?.activeFilters ?? t('filters.active'),
    filters: labels?.filters ?? 'Filters',
    clearAll: labels?.clearAll ?? 'Clear all',
    removeFilter: labels?.removeFilter ?? ((field: string, value: string) => t('filters.remove', { field, value })),
  };
}
